# enclosure: generated by ShapeBridge (https://github.com/gazi-faysal-jubayer/shapebridge)
# Units: mm. Edit the parameters below; geometry updates from them.

import math
import cadquery as cq

# sketch planes: (x direction, normal); the normal is x × y
FRAMES = {"XY": ((1, 0, 0), (0, 0, 1)), "XZ": ((1, 0, 0), (0, -1, 0)), "YZ": ((0, 1, 0), (1, 0, 0))}


def plane(base, offset):
    x, n = FRAMES[base]
    return cq.Workplane(cq.Plane(origin=tuple(c * offset for c in n), xDir=x, normal=n))


def build(length=100, width=60, height=35, wall=2.5, radius=6):
    # body
    def tool_body():
        return plane("XY", 0).polyline([(0, 0), (length, 0), (length, width), (0, width)]).close().extrude(height)
    result = tool_body()
    # round
    result = result.edges("|Z").fillet(radius)
    # hollow
    result = result.faces(">Z").shell(-(wall))
    return result


result = build()
if "show_object" in globals():
    show_object(result)
elif __name__ == "__main__":
    cq.exporters.export(result, "enclosure.step")
